{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C08"],
      "claim": "L-1-[18F]fluoroethyl-tryptophan, a modified tryptophan analogue, was directly shown to cross the BBB and accumulate in intracranial glioma in mice, supporting that tryptophan-derived scaffolds can retain CNS access despite structural modification.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "AZD0530, a tryptophan amide with a hydroxamate and no free amino acid, was detected in plasma, brain, and CSF of mice with a 16 h brain half-life, demonstrating that amide-modified tryptophan derivatives can achieve meaningful CNS exposure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "A large tryptophan amide bearing a basic piperazine and fluorinated aryl groups crossed the BBB and was detected in mouse brain 2 h after exposure, supporting CNS access for high-MW basic tryptophan amides.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "PBR28, which shares the N-acetyl-N-(2-methoxybenzyl) capping fragment with the query, showed satisfactory initial brain uptake in rhesus macaque PET imaging, supporting the brain-penetrant character of that motif.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "5-[18F]FEHTrp, a tryptophan hydroxamate with a free carboxyl and N-O-fluoroethyl group, showed low brain uptake in mice, indicating that certain polar/ionized tryptophan modifications can impair CNS access; this is less transferable to the query because the query lacks the free carboxyl and N-O group.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Despite physicochemical liabilities such as high molecular weight, basic piperidines, and an efflux-oriented prior, multiple direct in vivo measurements on structurally related tryptophan amides and the shared PBR28-like capping motif demonstrate meaningful BBB penetration. The low-uptake hydroxamate analogues are less transferable because they contain a free carboxyl and polar N-O group absent in the query. Overall prediction: pass.",
  "evidence_gaps": [
    "No direct brain/plasma or CSF measurement exists for the exact query molecule.",
    "No experimental P-gp/BCRP efflux data are available for the query.",
    "The most relevant analogues have only moderate-to-low Morgan similarity (~0.27-0.31).",
    "The impact of the second basic piperidine on brain penetration is not directly covered by the evidence set."
  ],
  "new_evidence_assessment": [
    {
      "applicability": "moderate",
      "card_ids": ["C08", "C01", "C06", "C11"],
      "decision_effect": "strengthened",
      "direction": "supportive",
      "family": "tryptophan-derived and PBR28-like CNS penetrants"
    },
    {
      "applicability": "low",
      "card_ids": ["C14", "C13"],
      "decision_effect": "no_change",
      "direction": "contradictory",
      "family": "polar tryptophan hydroxamates with low brain uptake"
    }
  ],
  "revision_action": "initial"
}

